package org.apache.commons.lang3.time;

import org.junit.Test;
import static org.junit.Assert.*;

import java.util.Locale;
import java.util.TimeZone;

public class AgentBRT_Lang_9_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        String pattern = "yyyy-MM-dd'T'HH:mm:ss.SSSXXX'Extra'";
        TimeZone timeZone = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.US;

        try {
            new FastDateParser(pattern, timeZone, locale);
            fail("Expected IllegalArgumentException due to unparsed pattern part");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Failed to parse"));
        }
    }
}

